classdef multi_lin_sys < matlab.System
    % multi_lin_sys
    % Multi-trim-point LPV helicopter linear system in the NED frame.
    %
    % Trim points are selected by the NED down-direction trim speed:
    %   v_down = 10 kt -> (A_10, B_10)
    %   v_down =  5 kt -> (A_5,  B_5)
    %   v_down =  0 kt -> (A_0,  B_0)
    %
    % The parameter-dependent matrices are generated by piecewise-linear
    % interpolation:
    %
    %   if 0 <= v_down <= 5:
    %       A(v_down) = (1-lambda)*A_0 + lambda*A_5
    %       B(v_down) = (1-lambda)*B_0 + lambda*B_5
    %       lambda = v_down/5
    %
    %   if 5 < v_down <= 10:
    %       A(v_down) = (1-lambda)*A_5 + lambda*A_10
    %       B(v_down) = (1-lambda)*B_5 + lambda*B_10
    %       lambda = (v_down-5)/5
    %
    % State definition:
    %   x = [u, w, q, theta, v, p, r, phi, psi]'
    %
    % Input definition:
    %   delta = [cyc_lat, cyc_lon, coll, ped]'
    %
    % This block only computes the continuous-time derivative:
    %   x_dot = A(v_down)*x + B(v_down)*delta
    %
    % The integration of x_dot should be performed outside this block by
    % a Simulink Integrator or Discrete-Time Integrator. Output selection
    % should also be performed outside this block.
    %
    % MATLAB System block inputs:
    %   input 1: x, 9x1 state vector
    %   input 2: delta, 4x1 control vector
    %   input 3: v_down, scalar scheduling variable in knots
    %
    % MATLAB System block output:
    %   output 1: x_dot, 9x1 state derivative vector

    properties (Nontunable)
        % Trim-point matrices.


        A_10 = zeros(9,9)
        B_10 = zeros(9,4)
        A_5  = zeros(9,9)
        B_5  = zeros(9,4)
        A_0  = zeros(9,9)
        B_0  = zeros(9,4)

        % If true, v_down is clamped to the interpolation range [0,10].
        % If false, linear extrapolation is used outside the range.

        
        ClampSchedulingVariable = true
    end

    methods (Access = protected)
        function setupImpl(obj)
            obj.validateParameters();
        end

        function x_dot = stepImpl(obj,x,delta,v_down)
            x = double(x(:));
            delta = double(delta(:));
            v_down = double(v_down);

            if numel(x) ~= 9
                error('multi_lin_sys:StateDimension', ...
                    'The state input x must be a 9-by-1 vector.');
            end

            if numel(delta) ~= 4
                error('multi_lin_sys:InputDimension', ...
                    'The control input delta must be a 4-by-1 vector.');
            end

            if ~isscalar(v_down) || ~isfinite(v_down)
                error('multi_lin_sys:SchedulingVariable', ...
                    'v_down must be a finite scalar in knots.');
            end

            [A_now,B_now] = obj.interpolateMatrices(v_down);
            x_dot = A_now*x + B_now*delta;
        end

        function num = getNumInputsImpl(~)
            num = 3;
        end

        function num = getNumOutputsImpl(~)
            num = 1;
        end

        function sizeOut = getOutputSizeImpl(~)
            sizeOut = [9,1];
        end

        function typeOut = getOutputDataTypeImpl(~)
            typeOut = 'double';
        end

        function complexOut = isOutputComplexImpl(~)
            complexOut = false;
        end

        function fixedOut = isOutputFixedSizeImpl(~)
            fixedOut = true;
        end

        function flag = supportsMultipleInstanceImpl(~)
            flag = true;
        end
    end

    methods (Access = private)
        function validateParameters(obj)
            if ~isequal(size(obj.A_10),[9,9]) || ...
                    ~isequal(size(obj.A_5),[9,9]) || ...
                    ~isequal(size(obj.A_0),[9,9])
                error('multi_lin_sys:StateMatrixDimension', ...
                    'A_10, A_5 and A_0 must all have size 9-by-9.');
            end

            if ~isequal(size(obj.B_10),[9,4]) || ...
                    ~isequal(size(obj.B_5),[9,4]) || ...
                    ~isequal(size(obj.B_0),[9,4])
                error('multi_lin_sys:InputMatrixDimension', ...
                    'B_10, B_5 and B_0 must all have size 9-by-4.');
            end
        end

        function [A_now,B_now] = interpolateMatrices(obj,v_down)
            if obj.ClampSchedulingVariable
                v = min(max(v_down,0),10);
            else
                v = v_down;
            end

            if v <= 5
                lambda = v/5;
                A_now = (1-lambda)*obj.A_0 + lambda*obj.A_5;
                B_now = (1-lambda)*obj.B_0 + lambda*obj.B_5;
            else
                lambda = (v-5)/5;
                A_now = (1-lambda)*obj.A_5 + lambda*obj.A_10;
                B_now = (1-lambda)*obj.B_5 + lambda*obj.B_10;
            end
        end
    end
end
